import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { GoogleGenerativeAI } from "@google/generative-ai";

const genAI = new GoogleGenerativeAI(process.env.GEMINI_API_KEY || "");

export async function POST(request: Request) {
  if (!process.env.GEMINI_API_KEY) {
    return new NextResponse(JSON.stringify({ error: "Missing GEMINI_API_KEY." }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }

  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) {
    return new NextResponse(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

  const { recipientInfo, myProduct, valueProp, cta, tone } = await request.json();

  if (!recipientInfo) {
    return new NextResponse(JSON.stringify({ error: "Recipient info is required" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  try {
    const model = genAI.getGenerativeModel({ model: "gemini-flash-latest" });

    const prompt = `You are a world-class Cold Email Copywriter. Your goal is to write a high-conversion cold email based on the following details:

    Recipient Context: ${recipientInfo}
    What I Offer: ${myProduct}
    Key Value Proposition: ${valueProp}
    Call to Action (CTA): ${cta}
    Tone of Voice: ${tone}

    Instructions:
    1. **Subject Line:** Write a short, curiosity-inducing subject line (no more than 5 words).
    2. **Opening:** Keep it brief. Acknowledge the recipient's context without being creepy.
    3. **The Hook:** Transition quickly into the problem you solve or the value you provide.
    4. **Social Proof (Optional):** If implied, mention results.
    5. **CTA:** Make the ask low-friction (e.g. "Open to a chat?" rather than "Book 30 mins").
    6. **Length:** Keep the entire email under 150 words.
    7. **No Cliches:** Avoid "I hope this finds you well" or "I wanted to reach out."

    Write the email now.`;

    const result = await model.generateContent(prompt);
    const response = await result.response;
    const emailText = response.text();

    return new NextResponse(JSON.stringify({ email: emailText }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error(error);
    return new NextResponse(JSON.stringify({ error: "Failed to generate email." }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
}